scripts:
await page.goto('https://practice.expandtesting.com/form-validation');
await page.getByLabel('Contact Name').fill('Alex Example');
await page.getByLabel('Contact number').fill('012-3456789');
await page.getByLabel('Date').fill('15 January 2030');
await page.getByLabel('Payment').selectOption({label:'Card'});
await page.getByRole('button', {name:'Submit'}).click();
await page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText.includes('Thank you') ? document.body.innerText.match(/[^.!?]*thank[^.!?]*[.!?]/i)?.[0] || 'Thank you' : document.body.innerText.slice(0,500), values: [], answer: document.body.innerText.match(/[^.!?]*thank[^.!?]*[.!?]/i)?.[0] || ''}))

await page.goto('https://practice.expandtesting.com/form-validation');
await page.evaluate(() => {
  const controls = [...document.querySelectorAll('input, select, textarea')];
  for (const el of controls) {
    const label = [...(el.labels || [])].map(x => x.innerText).join(' ');
    const text = `${label} ${el.name} ${el.id} ${el.placeholder}`.toLowerCase();
    if (/contact.?name/.test(text)) el.value = 'Alex Example';
    else if (/contact.?number/.test(text)) el.value = '012-3456789';
    else if (/date|pickup/.test(text) && el.tagName !== 'SELECT') el.value = el.type === 'date' ? '2030-01-15' : '15 January 2030';
    else if (el.tagName === 'SELECT' && /payment/.test(text)) {
      const option = [...el.options].find(o => /card/i.test(o.text));
      if (option) el.value = option.value;
    }
    el.dispatchEvent(new Event('input', {bubbles:true}));
    el.dispatchEvent(new Event('change', {bubbles:true}));
  }
  const form = document.querySelector('form');
  if (form) form.requestSubmit();
});
await page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText.slice(-1000), values: [], answer: document.body.innerText.match(/[^.!?]*thank[^.!?]*[.!?]/i)?.[0] || ''}))
